package com.nigson.acceptance.order;

import java.util.*;
import java.time.*;
import org.junit.jupiter.api.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.*;
import org.springframework.transaction.support.TransactionTemplate;
import com.nigson.acceptance.fulfillment.ShipmentFixture;
import com.nigson.commerce.inventory.InventoryAuthority;
import com.nigson.commerce.order.*;
import com.nigson.commerce.payment.*;
import com.nigson.commerce.platform.*;
import com.nigson.commerce.pricing.PricingAuthority;
import com.nigson.shared.security.ActorAssertion;
import static org.assertj.core.api.Assertions.*;

class ReturnPersistenceTest {
 ShipmentFixture f;ReturnService service;ActorAssertion.Actor customer,finance;UUID financeParty;JdbcTemplate jdbc;
 @BeforeEach void setup(){String url=System.getenv("NIGSON_TEST_JDBC_URL");Assumptions.assumeTrue(url!=null,"fulfillment-check supplies isolated PostgreSQL");if(!url.matches("jdbc:postgresql://127.0.0.1:[0-9]+/nigson"))throw new IllegalArgumentException("LOCAL_TEST_DB_REQUIRED");var ds=new DriverManagerDataSource(url+"?currentSchema=commerce","nigson_commerce_app","mock-commerce-runtime");jdbc=new JdbcTemplate(ds);var manager=new DataSourceTransactionManager(ds);f=new ShipmentFixture(jdbc,manager);var clock=Clock.systemUTC();var authority=new OrderAuthority(jdbc,new PricingAuthority(jdbc,clock,3,"SYNTHETIC_DISTRIBUTOR_BUY"),clock);var audit=new AuditWriter(jdbc,clock,f.metrics);var commands=new PlatformStore(jdbc,manager,clock,f.metrics);var policy=new OrderPolicy(true,"test","MOCK","SYNTHETIC_OFFLINE_ONLY",List.of(f.location),900);var refunds=new JdbcPaymentRepository(jdbc,clock,policy);service=new ReturnService(jdbc,manager,authority,new InventoryAuthority(jdbc),new PricingAuthority(jdbc,clock,3,"SYNTHETIC_DISTRIBUTOR_BUY"),f.inventory.ledger,refunds,new PaymentPolicy(true,"test",false,"SYNTHETIC_TWO_PERSON",300),policy,commands,audit,clock);customer=new ActorAssertion.Actor(f.inventory.orders.party,"https://identity.synthetic.invalid/realms/test",f.inventory.orders.party.toString(),null,Set.of("CUSTOMER"),Set.of(),null);financeParty=UUID.randomUUID();jdbc.update("INSERT INTO commerce.party(id,created_by,updated_by,identity_issuer,identity_subject,email,display_name) VALUES (?,'test','test',?,?,?,'Synthetic return finance')",financeParty,"https://identity.synthetic.invalid/realms/test",financeParty.toString(),financeParty+"@example.invalid");jdbc.update("INSERT INTO commerce.staff_role_assignment(id,created_by,updated_by,party_id,role,granted_by) VALUES (?,'test','test',?,'FINANCE',?)",UUID.randomUUID(),financeParty,financeParty);finance=new ActorAssertion.Actor(financeParty,"https://identity.synthetic.invalid/realms/test",financeParty.toString(),null,Set.of("FINANCE"),Set.of(),Instant.now());jdbc.update("UPDATE commerce.sales_order SET commercial_snapshot=?::jsonb WHERE id=?","{\"returnsPolicyRevision\":\"SYNTHETIC_RETURNS_POLICY\"}",f.order);jdbc.update("UPDATE commerce.sales_order SET subtotal=100,discount_total=0,tax_total=0,delivery_total=0,grand_total=100 WHERE id=?",f.order);jdbc.update("UPDATE commerce.payment_attempt SET expected_amount=100 WHERE order_id=?",f.order);f.inventory.admin.update("UPDATE commerce.payment_transaction SET settled_amount=100 WHERE attempt_id IN(SELECT id FROM commerce.payment_attempt WHERE order_id=?)",f.order);}
 @AfterEach void cleanup(){if(f!=null){jdbc.update("DELETE FROM commerce.return_request WHERE order_id=?",f.order);f.inventory.admin.update("DELETE FROM commerce.refund_line WHERE refund_id IN(SELECT id FROM commerce.refund WHERE order_id=?)",f.order);jdbc.update("DELETE FROM commerce.refund WHERE order_id=?",f.order);jdbc.update("DELETE FROM commerce.idempotency_record WHERE principal_key=? OR principal_key=?","return-",financeParty.toString());if(financeParty!=null){jdbc.update("DELETE FROM commerce.staff_role_assignment WHERE party_id=?",financeParty);jdbc.update("DELETE FROM commerce.party WHERE id=?",financeParty);}f.close();}}
 ReturnValues.View delivered(){var shipment=f.create("5","MANUAL","SYNTH_RETURN_SHIPMENT","return-ship");f.service.dispatch(f.inventory.actor,shipment.id(),0,"Synthetic physical handover for return","return-dispatch",UUID.randomUUID());f.service.delivered(f.inventory.actor,shipment.id(),1,new com.nigson.commerce.fulfillment.FulfillmentValues.Delivery(Instant.now(),"Synthetic delivery before return"),"return-delivery",UUID.randomUUID());return service.get(customer,f.order,false);}
 ReturnValues.Item create(ReturnValues.View view,String quantity,String key){return service.create(customer,f.order,view.orderVersion(),new ReturnValues.Request(f.line,quantity,"Synthetic customer product return"),key,UUID.randomUUID());}
 @Test void deliveredCustomerReturnsAreReviewedReceivedAndLinkedToFinanceRefundOnce(){
  var view=delivered();assertThat(view.delivered()).isTrue();assertThat(view.lines()).hasSize(1);assertThat(view.lines().getFirst().availableQuantity()).isEqualTo("5");assertThat(view.paystackRefundAvailable()).isTrue();assertThat(view.refundableAmount()).isEqualTo("100.00");
  var created=create(view,"2.000","return-create");assertThat(created.state()).isEqualTo("REQUESTED");assertThat(created.quantity()).isEqualTo("2");assertThat(created.policyRevision()).isEqualTo("SYNTHETIC_RETURNS_POLICY");assertThat(created.version()).isZero();
  var approved=service.review(f.inventory.actor,created.id(),0,new ReturnValues.Review(true,"Synthetic Operations review","Return through the approved support channel"),"return-review",UUID.randomUUID());assertThat(approved.state()).isEqualTo("APPROVED");assertThat(approved.instructions()).contains("approved support channel");
  var received=service.receive(f.inventory.actor,approved.id(),1,new ReturnValues.Receipt("SYNTH_RETURN_RECEIPT",true,"Synthetic physical inspection and restock"),"return-receipt",UUID.randomUUID());assertThat(received.state()).isEqualTo("RECEIVED");assertThat(received.restock()).isTrue();assertThat(f.value("on_hand")).isEqualByComparingTo("7");
  var refunded=service.refund(finance,received.id(),2,new ReturnValues.Refund("10.00","Synthetic approved return refund"),"return-refund",UUID.randomUUID());assertThat(refunded.refundId()).isNotNull();assertThat(refunded.refundState()).isEqualTo("REQUESTED");assertThat(jdbc.queryForObject("SELECT count(*) FROM commerce.refund WHERE order_id=?",Integer.class,f.order)).isEqualTo(1);
  assertThat(service.get(customer,f.order,false).requests()).hasSize(1);
  assertThatThrownBy(()->service.receive(f.inventory.actor,received.id(),3,new ReturnValues.Receipt("SYNTH_RETURN_RECEIPT_2",true,"Synthetic duplicate physical receipt"),"return-receipt-again",UUID.randomUUID())).hasMessage("INVALID_TRANSITION");
 }

 @Test void ownerVersionAndCurrentRoleAreRechecked(){
  var view=delivered();var otherParty=UUID.randomUUID();jdbc.update("INSERT INTO commerce.party(id,created_by,updated_by,identity_issuer,identity_subject,email,display_name) VALUES (?,'test','test',?,?,?,'Synthetic foreign return actor')",otherParty,"https://identity.synthetic.invalid/realms/test",otherParty.toString(),otherParty+"@example.invalid");var other=new ActorAssertion.Actor(otherParty,"https://identity.synthetic.invalid/realms/test",otherParty.toString(),null,Set.of("CUSTOMER"),Set.of(),null);try{assertThatThrownBy(()->service.create(other,f.order,view.orderVersion(),new ReturnValues.Request(f.line,"1","Synthetic foreign customer return"),"foreign-return",UUID.randomUUID())).hasMessage("NOT_FOUND");assertThatThrownBy(()->service.create(customer,f.order,view.orderVersion()+1,new ReturnValues.Request(f.line,"1","Synthetic stale customer return"),"stale-return",UUID.randomUUID())).hasMessage("VERSION_MISMATCH");var created=create(view,"1","return-role");jdbc.update("UPDATE commerce.staff_role_assignment SET revoked_at=now() WHERE party_id=? AND role='OPERATIONS'",f.inventory.actor.party());assertThatThrownBy(()->service.review(f.inventory.actor,created.id(),0,new ReturnValues.Review(true,"Synthetic revoked review","Synthetic revoked instructions"),"return-revoked",UUID.randomUUID())).hasMessage("ACCESS_DENIED");}finally{jdbc.update("DELETE FROM commerce.idempotency_record WHERE principal_key=?",otherParty.toString());jdbc.update("DELETE FROM commerce.party WHERE id=?",otherParty);}
 }

 @Test void populatedReturnRollbackRefusesBeforeDroppingEvidence()throws Exception{
  var view=delivered();create(view,"1","return-rollback");String rollback=java.nio.file.Files.readString(java.nio.file.Path.of("src/main/resources/db/changelog/038-bp1-customer-returns-rollback.sql"));assertThatThrownBy(()->f.inventory.admin.execute(rollback)).isInstanceOf(org.springframework.dao.DataAccessException.class);assertThat(jdbc.queryForObject("SELECT count(*) FROM commerce.return_request WHERE order_id=?",Integer.class,f.order)).isEqualTo(1);
 }
}
